import Axios from "axios";
import { getTimestamp, makeSignature } from "./signature";
import { LOCALSTORAGE_KEY } from "./constant/localstorage";
import { getData } from "@/hooks/useLocalStorage";
import Swal from "sweetalert2";

export const axios = Axios.create({
  baseURL: import.meta.env.VITE_API_URL || "http://localhost:3000",
});

// Request Interceptor: Inject JWT Token & Cryptographic HMAC Signature
axios.interceptors.request.use(
  async (config) => {
    const token = getData(LOCALSTORAGE_KEY.TOKEN);
    const timestamp = getTimestamp();

    if (token) {
      config.headers.Authorization = `Bearer ${token}`;
    }

    const signature = makeSignature(
      0,
      timestamp,
      config.data || {},
      config.data instanceof FormData
    );

    config.headers["sig"] = signature;
    config.headers["email"] = "0";
    config.headers["timestamp"] = timestamp.toString();

    return config;
  },
  (error) => Promise.reject(error)
);

// Response Interceptor: Centralized 401 Session Invalidation & Expiration Handling
axios.interceptors.response.use(
  (response) => response,
  async (error) => {
    const status = error.response?.status;
    const data = error.response?.data;

    if (status === 401) {
      const isLoginPage = window.location.pathname.includes("/login") || window.location.hash.includes("/login");

      if (!isLoginPage) {
        localStorage.removeItem(LOCALSTORAGE_KEY.TOKEN);
        localStorage.removeItem(LOCALSTORAGE_KEY.USER);

        let msg = "Sesi telah kedaluwarsa.";
        if (data?.message) {
          msg = typeof data.message === "string" ? data.message : (data.message.msg_ind || JSON.stringify(data.message));
        }

        await Swal.fire({
          title: msg.split(",")[0],
          text: "Sesi telah kedaluwarsa.",
          icon: "warning",
          confirmButtonText: "Go to Login",
          allowOutsideClick: false,
          allowEscapeKey: false,
          confirmButtonColor: "#FFD700",
        });

        window.location.href = "/login";
      }
    }
    return Promise.reject(error);
  }
);

import CryptoJS from "crypto-js";

export const getTimestamp = () => new Date().getTime();

function flattenObject(obj: any, prefix: string = ""): any {
  let flattened: any = {};
  for (const key in obj) {
    if (Object.prototype.hasOwnProperty.call(obj, key)) {
      const value = obj[key];
      const prefixedKey = prefix === "" ? key : `${prefix}.${key}`;
      if (typeof value === "object" && value !== null && !Array.isArray(value)) {
        const nested = flattenObject(value, prefixedKey);
        flattened = { ...flattened, ...nested };
      } else if (Array.isArray(value)) {
        flattened[prefixedKey] = "";
      } else {
        flattened[prefixedKey] = value;
      }
    }
  }
  return flattened;
}

function formatObject(obj: any): string {
  const flattened = flattenObject(obj);
  let result = "";
  Object.keys(flattened)
    .sort()
    .forEach((key) => {
      const value = flattened[key];
      result += `${key}${value}`;
    });
  return result;
}

export const makeSignature = (email: number, timestamp: number, data: any, isFormData?: boolean) => {
  const formDataObject: any = { email, timestamp };
  if (isFormData) {
    for (const pair of data.entries()) {
      formDataObject[pair[0]] = pair[1];
    }
  }
  const newPayload = { email, ...data, timestamp };
  const newData = isFormData ? formDataObject : newPayload;
  const finalPayload = formatObject(newData);
  return CryptoJS.SHA1(finalPayload);
};

import { Client } from "@stomp/stompjs";
import { useCallback, useEffect, useRef, useState } from "react";
import type { INotificationValue } from "../types/NotificationResponse";

interface UseStompNotificationsProps {
  onNewNotification?: () => void;
}

type ConnectionStatus = "connecting" | "connected" | "disconnected" | "error";

export const useStompNotifications = ({
  onNewNotification,
}: UseStompNotificationsProps = {}) => {
  const [notifications, setNotifications] = useState<INotificationValue[]>([]);
  const [connectionStatus, setConnectionStatus] = useState<ConnectionStatus>("disconnected");

  const clientRef = useRef<Client | null>(null);
  const reconnectTimeoutRef = useRef<ReturnType<typeof setTimeout> | undefined>(undefined);
  const isInitialLoadRef = useRef(true);
  const onNewNotificationRef = useRef(onNewNotification);

  useEffect(() => {
    onNewNotificationRef.current = onNewNotification;
  }, [onNewNotification]);

  useEffect(() => {
    isInitialLoadRef.current = false;
  }, []);

  const WEBSOCKET_URL = import.meta.env.VITE_WEBSOCKET_URL;

  useEffect(() => {
    const connectWebSocket = () => {
      if (clientRef.current && clientRef.current.active) return;
      if (!WEBSOCKET_URL) {
        setConnectionStatus("error");
        return;
      }

      if (reconnectTimeoutRef.current) clearTimeout(reconnectTimeoutRef.current);

      const wsUrl = `${WEBSOCKET_URL}/web-socket`;
      setConnectionStatus("connecting");

      try {
        const client = new Client({
          brokerURL: wsUrl,
          reconnectDelay: 5000,
          heartbeatIncoming: 4000,
          heartbeatOutgoing: 4000,
        });

        client.onConnect = (frame) => {
          setConnectionStatus("connected");
          client.subscribe("/queue/notification", (message) => {
            try {
              const response: INotificationValue = JSON.parse(message.body);
              setNotifications((prev) => [response, ...prev]);
              if (!isInitialLoadRef.current && onNewNotificationRef.current) {
                onNewNotificationRef.current();
              }
            } catch (parseError) {
              console.error("Error parsing notification:", parseError);
            }
          });
        };

        client.onStompError = () => {
          setConnectionStatus("error");
          reconnectTimeoutRef.current = setTimeout(connectWebSocket, 5000);
        };

        client.onWebSocketClose = (event) => {
          setConnectionStatus("disconnected");
          if (event.code !== 1000) {
            reconnectTimeoutRef.current = setTimeout(connectWebSocket, 5000);
          }
        };

        clientRef.current = client;
        client.activate();
      } catch (error) {
        setConnectionStatus("error");
        reconnectTimeoutRef.current = setTimeout(connectWebSocket, 5000);
      }
    };

    connectWebSocket();

    return () => {
      if (reconnectTimeoutRef.current) clearTimeout(reconnectTimeoutRef.current);
      if (clientRef.current) {
        clientRef.current.deactivate();
        clientRef.current = null;
      }
    };
  }, [WEBSOCKET_URL]);

  const handleMarkAllRead = useCallback(() => {
    setNotifications((prev) => prev.map((n) => ({ ...n, is_read: true })));
  }, []);

  const clearNotifications = useCallback(() => {
    setNotifications([]);
  }, []);

  return { notifications, connectionStatus, handleMarkAllRead, clearNotifications };
};

import { ROUTES } from "@/config/constant/routes";
import { Navigate } from "react-router-dom";
import { getData } from "@/hooks/useLocalStorage";
import { LOCALSTORAGE_KEY } from "@/config/constant/localstorage";
import { defaultModules } from "@/config/constant/DefaultModules";

interface ModuleGuardProps {
  children: React.ReactNode;
  moduleKey: string;
}

const ModuleGuard = ({ children, moduleKey }: ModuleGuardProps) => {
  const userData = getData(LOCALSTORAGE_KEY.USER);
  const userRole = userData?.role_code;
  const modules = userData?.modules || [];

  // SUPERADMIN: Access to all modules except designated exclusions
  if (userRole === "SUPERADMIN") {
    if (moduleKey === "inventory") {
      return <Navigate to={ROUTES.DASHBOARD} replace />;
    }
    return <>{children}</>;
  }

  // Standard Role: Access restricted to default whitelist or explicit user modules
  const hasAccess = defaultModules.includes(moduleKey) || modules.includes(moduleKey);

  if (!hasAccess) {
    return <Navigate to={ROUTES.DASHBOARD} replace />;
  }

  return <>{children}</>;
};

export default ModuleGuard;

import { Navigate, Outlet } from "react-router-dom";
import { getData } from "@/hooks/useLocalStorage";
import { LOCALSTORAGE_KEY } from "@/config/constant/localstorage";
import { ROUTES } from "@/config/constant/routes";

const PrivateRoute = () => {
  const token = getData(LOCALSTORAGE_KEY.TOKEN);

  if (!token) {
    return <Navigate to={ROUTES.LOGIN} replace />;
  }

  return <Outlet />;
};

export default PrivateRoute;

import axios from "@/config/axios";
import { ENDPOINTS } from "@/config/constant/endpoint";
import type { AddCategoryRequest } from "@/pages/PersonAccess/schema";
import type { ICategoryResponse } from "@/pages/PersonAccess/types/CategoryResponse";
import type { IPersonAccessDefaultResponse } from "@/pages/PersonAccess/types/PersonAccessDefaultResponse";

export const PersonAccessServices = {
  createCategory: async (data: AddCategoryRequest): Promise<IPersonAccessDefaultResponse> => {
    const response = await axios.post<IPersonAccessDefaultResponse>(
      ENDPOINTS.PERSON_ACCESS.CATEGORY.CREATE,
      data
    );
    return response.data;
  },

  updateCategory: async ({ id, data }: { id: string; data: AddCategoryRequest }): Promise<IPersonAccessDefaultResponse> => {
    const URL = ENDPOINTS.PERSON_ACCESS.CATEGORY.UPDATE.replace(":id", id);
    const response = await axios.put<IPersonAccessDefaultResponse>(URL, data);
    return response.data;
  },

  deleteCategory: async ({ id, password }: { id: string; password: string }): Promise<IPersonAccessDefaultResponse> => {
    const URL = ENDPOINTS.PERSON_ACCESS.CATEGORY.DELETE.replace(":id", id);
    const response = await axios.delete<IPersonAccessDefaultResponse>(URL, {
      data: { password }
    });
    return response.data;
  },

  getAllCategory: async (params?: string): Promise<ICategoryResponse> => {
    const response = await axios.get<ICategoryResponse>(
      ENDPOINTS.PERSON_ACCESS.CATEGORY.GET_ALL,
      { params: { search: params } }
    );
    return response.data;
  },
};

import { AxiosError } from "axios";
import { toast } from "sonner";

export interface ApiError {
  code: number;
  message: string;
  errors?: Record<string, string>;
  result: null;
}

export const formatErrorMessage = (error: unknown): string[] => {
  const axiosError = error as AxiosError<ApiError>;
  const apiError = axiosError.response?.data;

  if (!apiError) {
    return [axiosError.message || "An error occurred"];
  }

  // Handle field-specific validation errors dictionary
  if (apiError.errors && Object.keys(apiError.errors).length > 0) {
    return Object.values(apiError.errors);
  }

  // Handle general API error message
  if (apiError.message) {
    const formattedMessage =
      apiError.message.charAt(0).toUpperCase() + apiError.message.slice(1);
    return [formattedMessage];
  }

  return ["An error occurred"];
};

export const showErrorToast = (error: AxiosError<ApiError>) => {
  const errors = formatErrorMessage(error);
  const errorList = errors.map((err) => `• ${err}`).join("\n");

  toast.error("Error", {
    description: errorList,
    style: { whiteSpace: "pre-line" },
  });
};

